{
  "title": "A Tasting Walk Through Kyoto",
  "summary": "A slower day for Rin's appetite, wandering from temple calm to market snacks and a proper evening meal.",
  "stops": [
    {
      "poi_id": "p12",
      "kind": "activity",
      "must_do_id": "m2",
      "note": "Kept as the one must-do. Shoes off, phone down, eyes up."
    },
    {
      "poi_id": "p4",
      "kind": "activity",
      "must_do_id": null,
      "note": "Rin gets her market wander. Graze slowly, the stalls reward patience."
    },
    {
      "poi_id": "p17",
      "kind": "meal",
      "must_do_id": null,
      "note": "A proper lunch that respects the budget. Slurp loudly, it is a compliment."
    },
    {
      "poi_id": "p7",
      "kind": "activity",
      "must_do_id": null,
      "note": "A gentle stroll to settle lunch before the evening appetite returns."
    },
    {
      "poi_id": "p19",
      "kind": "meal",
      "must_do_id": null,
      "note": "Dinner with options for everyone, and Rin can keep eating her way through the day."
    }
  ]
}
